// Update the setActiveSlide function to include stopping videos when switching slides
function setActiveSlide(lightboxId, slideIndex) {
    // Get the lightbox element by its ID
    const lightbox = document.getElementById(`Lightbox_${lightboxId}`);

    if (!lightbox) return; // Exit if lightbox is not found

    // Get all slides inside the specific lightbox
    const slides = lightbox.getElementsByClassName('slide');

    const totalSlides = slides.length;

    // If no slides are found, exit the function
    if (totalSlides === 0) return;

    // Remove any previous active/next/previous classes and hide all slides
    Array.from(slides).forEach((slide) => {
        slide.classList.remove('active-slide', 'next-slide', 'previous-slide');
        slide.style.display = 'none'; // Hide all slides initially

        // Stop the video if it's not the active slide
        const video = slide.querySelector('video');
        if (video) {
            video.pause(); // Pause video when it's not active
        }
    });

    // Add active, next, and previous classes to the appropriate slides
    const previousIndex = (slideIndex - 1 + totalSlides) % totalSlides;
    const nextIndex = (slideIndex + 1) % totalSlides;

    // Assign active class to the current slide
    slides[slideIndex].style.display = 'flex';
    slides[slideIndex].classList.add('active-slide');

    // Assign previous class to the previous slide
    slides[previousIndex].style.display = 'flex';
    slides[previousIndex].classList.add('previous-slide');

    // Assign next class to the next slide
    slides[nextIndex].style.display = 'flex';
    slides[nextIndex].classList.add('next-slide');

    // Store the last slide index in sessionStorage
    sessionStorage.setItem(`lastSlide_${lightboxId}`, slideIndex);

    // Trigger the slideChanged event
    const event = new CustomEvent("slideChanged", {
        detail: {
            lightboxId: lightboxId,
            slideIndex: slideIndex,
        },
    });
    lightbox.dispatchEvent(event); // Dispatch the custom event
}

function storeLastSlide(lightboxId, slideIndex) {
    sessionStorage.setItem(`lastSlide_${lightboxId}`, slideIndex);
}
// Function to navigate to a specific slide
function toSlide(lightboxId, slideIndex) {
    setActiveSlide(lightboxId, slideIndex);
    storeLastSlide(lightboxId, slideIndex);
}

function showSlide(lightboxId, e) {
    // Get all slides for the given slide group
    const slides = document.querySelectorAll(`.video slide${lightboxId}, .slide${lightboxId}`);


    // Ensure slideIndex is properly set when navigating
    if (e > slides.length) slideIndex = 1; // If e exceeds the number of slides, reset to 1
    else if (e < 1) slideIndex = slides.length; // If e is less than 1, go to the last slide
    else slideIndex = e; // Otherwise, use the value of e

    // Loop through all slides and hide them, removing the active/previous/next classes
    for (let n = 0; n < slides.length; n++) {
        slides[n].style.display = "none";
        slides[n].classList.remove("active-slide", "previous-slide", "next-slide");
    }

    // If there's only one slide, display it and mark it as active
    if (slides.length === 1) {
        slides[0].style.display = "flex";
        slides[0].classList.add("active-slide");

    } else {

        // Show the current slide and mark it as active
        if (slides[slideIndex - 1]) {
            slides[slideIndex - 1].style.display = "flex";
            slides[slideIndex - 1].classList.add("active-slide");
        }

        // Show the previous slide
        const prevIndex = slideIndex - 2 >= 0 ? slideIndex - 2 : slides.length - 1;
        if (slides[prevIndex]) {
            slides[prevIndex].style.display = "flex";
            slides[prevIndex].classList.add("previous-slide");
        }

        // Show the next slide
        const nextIndex = slideIndex < slides.length ? slideIndex : 0;
        if (slides[nextIndex]) {
            slides[nextIndex].style.display = "flex";
            slides[nextIndex].classList.add("next-slide");
        }
    }
    sessionStorage.setItem(`lastSlide_${lightboxId}`, slideIndex); // Store the new slideIndex in sessionStorage
}
// Function to change slides (use slideIndex properly)
function changeSlide(lightboxId, n) {
    const slides = document.getElementsByClassName(`slide${lightboxId}`);

    slideIndex += n; // Increment or decrement slideIndex

    if (slideIndex < 1) {
        slideIndex = slides.length;
    } else if (slideIndex > slides.length) {
        slideIndex = 1;
    }

    showSlide(lightboxId, slideIndex); // Call showSlide with correct lightboxId and slideIndex
    document.dispatchEvent(new Event("slideChange"));
}
// Function to set up key events for navigation
function setKeys(lightboxId) {
    window.onkeydown = function(e) {
        const key = e.key || e.code;

        if (key === "Escape") {
            closeLightbox(lightboxId);
        } else if (key === "ArrowRight") {
            changeSlide(lightboxId, 1);
        } else if (key === "ArrowLeft") {
            changeSlide(lightboxId, -1);
        }
    };
}
// Initialize the pointer interaction
function setupPointer() {
    const Xmax = getHighestLightboxNumber();
    const pointerElement = document.getElementById("before-pointer");

    pointerElement.onclick = function() {
        openLightbox(Xmax);
        showSlide(Xmax, slideIndex); // Start from the last known slide
    };
}
// Function to get the highest lightbox number
function getHighestLightboxNumber() {
    const lightboxes = document.querySelectorAll('[id^="Lightbox_"]');
    let highest = 0;
    lightboxes.forEach((lightbox) => {
        const id = lightbox.id;
        const number = parseInt(id.replace("Lightbox_", ""));
        if (number > highest) highest = number;
    });
    return highest;
}